const raw = $input.first().json;
const vms = raw.response || raw;
const list = Array.isArray(vms) ? vms : (vms.data || []);
const options = list.map(vm => `${vm.id} - ${vm.hostname} (${vm.state}, ${vm.plan || 'plan n/a'})`);
const cfg = $('When Form Submitted').item.json;
return [{ json: {
  vpsOptions: options,
  stackLabel: cfg['Stack'],
  notifyEmail: cfg['Notification Email'],
} }];

const raw = $input.item.json;
const action = raw.response || raw;
const cfg = $('Create Deployment Items').item.json;
return { json: { ...cfg, actionId: action.id, actionState: action.state } };

const raw = $input.item.json;
const action = raw.response || raw;
const cfg = $('Extract Deployment Action').item.json;
return { json: { ...cfg, finalState: action.state } };

const raw = $input.item.json;
const containers = raw.response || raw;
const cfg = $('Parse Deployment Status').item.json;
const list = Array.isArray(containers) ? containers : [];
const containerLines = list.map(c => `      - ${c.name}: ${c.status}`).join('\n') || '      (no containers reported yet)';
const secretLines = Object.entries(cfg.generatedSecrets || {}).map(([k,v]) => `      - ${k}: ${v}`).join('\n');
const block = [
  `- ${cfg.displayName} (deployed)`,
  `    Ports: ${cfg.hostPorts}`,
  `    Containers:`,
  containerLines,
  secretLines ? `    Generated credentials:\n${secretLines}` : null,
  cfg.appNotes ? `    Note: ${cfg.appNotes}` : null,
].filter(Boolean).join('\n');
return { json: { stackLabel: cfg.stackLabel, notifyEmail: cfg.notifyEmail, summaryBlock: block } };

const rows = $input.first().json.data;
const stackLabel = rows[0]?.stackLabel || 'Stack';
const notifyEmail = rows[0]?.notifyEmail;
const body = `Your ${stackLabel} deployment finished.\n\n` + rows.map(r => r.summaryBlock).join('\n\n');
return { json: { notifyEmail, stackLabel, body } };
